/** Ruler tilted -20° around the center: ticks along its lower edge. */
const rulerTicks: Stroke[] = Array.from({ length: 13 }, (_, i) => {
  const t = -0.36 + i * 0.06;
  const base = polar(0.5, 0.5, t, -20);
  const edge = polar(...base, 0.07, 70);
  return line(edge, polar(...edge, i % 2 ? 0.03 : 0.055, 250));
});

