/** One wavy seaweed ribbon rising from x at the bottom. */
const seaweedRibbon = (x: number, top: number): Stroke[] => {
  const left = line(...Array.from({ length: 30 }, (_, i): Point => { const t = i / 29; return [x - 0.03 + 0.05 * Math.sin(t * Math.PI * 3), 0.94 - (0.94 - top) * t]; }));
  const right = line(...Array.from({ length: 30 }, (_, i): Point => { const t = i / 29; return [x + 0.03 + 0.05 * Math.sin(t * Math.PI * 3) - 0.03 * t, 0.94 - (0.94 - top) * t]; }));
  return [left, right];
};

