/** Great Wall ridge line, sampled for the wall and its battlements. */
const RIDGE: Point[] = [[0.02, 0.7], [0.25, 0.42], [0.45, 0.56], [0.7, 0.3], [0.98, 0.5]];
const ridgeAt = (x: number): number => {
  for (let i = 1; i < RIDGE.length; i++) {
    const [x0, y0] = RIDGE[i - 1];
    const [x1, y1] = RIDGE[i];
    if (x <= x1) return y0 + ((y1 - y0) * (x - x0)) / (x1 - x0);
  }
  return RIDGE[RIDGE.length - 1][1];
};

/** Leaning tower of Pisa: a local-space stack of tiers, tilted by `place`. */
const pisaTiers: Stroke[] = [
  rect(-0.12, -0.36, 0.12, 0.36),
  ...[-0.24, -0.12, 0, 0.12, 0.24].map((y) => line([-0.12, y], [0.12, y])),
  ...[-0.3, -0.18, -0.06, 0.06, 0.18, 0.3].flatMap((y) => [-0.06, 0, 0.06].map((x) => line([x, y - 0.03], [x, y + 0.03]))),
  rect(-0.08, -0.44, 0.08, -0.36),
];

